/**
 * Mobile Calculator Application Engine - Production Artifact
 */

const INITIAL_STATE = {
  displayValue: '0',
  expression: '',
  firstOperand: null,
  waitingForSecondOperand: false,
  operator: null,
  history: []
};

let state = { ...INITIAL_STATE };
let hapticsEnabled = true;

// Precision helper for clean floating-point arithmetic
function roundPrecision(val, maxDecimals = 10) {
  const factor = Math.pow(10, maxDecimals);
  return Math.round((val + Number.EPSILON) * factor) / factor;
}

export function formatResult(num) {
  if (!Number.isFinite(num)) {
    return 'Error';
  }
  const strVal = String(roundPrecision(num));
  if (strVal.length > 12) {
    return num.toExponential(6);
  }
  return strVal;
}

export function executeOperation(first, second, op) {
  switch (op) {
    case '+':
      return first + second;
    case '-':
      return first - second;
    case '*':
      return first * second;
    case '/':
      if (second === 0) return NaN;
      return first / second;
    default:
      return second;
  }
}

export function inputDigit(digit) {
  triggerHaptic('digit');
  if (state.waitingForSecondOperand) {
    state.displayValue = digit;
    state.waitingForSecondOperand = false;
  } else {
    state.displayValue = state.displayValue === '0' ? digit : state.displayValue + digit;
  }
  updateUI();
}

export function inputDecimal() {
  triggerHaptic('digit');
  if (state.waitingForSecondOperand) {
    state.displayValue = '0.';
    state.waitingForSecondOperand = false;
    updateUI();
    return;
  }
  if (!state.displayValue.includes('.')) {
    state.displayValue += '.';
  }
  updateUI();
}

export function setOperation(nextOperator) {
  triggerHaptic('operator');
  const inputValue = parseFloat(state.displayValue);

  if (state.operator && state.waitingForSecondOperand) {
    state.operator = nextOperator;
    state.expression = `${state.firstOperand} ${formatOpSymbol(nextOperator)}`;
    updateUI();
    return;
  }

  if (state.firstOperand === null && !isNaN(inputValue)) {
    state.firstOperand = inputValue;
  } else if (state.operator) {
    const result = executeOperation(state.firstOperand, inputValue, state.operator);
    const formatted = formatResult(result);
    state.displayValue = formatted;
    state.firstOperand = Number.isFinite(result) ? result : null;
  }

  state.waitingForSecondOperand = true;
  state.operator = nextOperator;
  state.expression = `${state.displayValue} ${formatOpSymbol(nextOperator)}`;
  updateUI();
}

export function calculate() {
  triggerHaptic('equals');
  const inputValue = parseFloat(state.displayValue);
  if (state.operator === null || state.waitingForSecondOperand) {
    return;
  }

  const result = executeOperation(state.firstOperand, inputValue, state.operator);
  const formatted = formatResult(result);
  const fullExp = `${state.firstOperand} ${formatOpSymbol(state.operator)} ${inputValue}`;

  state.history.unshift({
    expression: fullExp,
    result: formatted,
    timestamp: Date.now()
  });

  state.displayValue = formatted;
  state.expression = `${fullExp} =`;
  state.firstOperand = null;
  state.operator = null;
  state.waitingForSecondOperand = false;

  updateUI();
  renderHistory();
}

export function toggleSign() {
  triggerHaptic('function');
  const val = parseFloat(state.displayValue);
  if (!isNaN(val) && val !== 0) {
    state.displayValue = String(-val);
    updateUI();
  }
}

export function percent() {
  triggerHaptic('function');
  const val = parseFloat(state.displayValue);
  if (!isNaN(val)) {
    const res = val / 100;
    state.displayValue = formatResult(res);
    updateUI();
  }
}

export function clear() {
  triggerHaptic('clear');
  state.displayValue = '0';
  state.expression = '';
  state.firstOperand = null;
  state.waitingForSecondOperand = false;
  state.operator = null;
  updateUI();
}

function formatOpSymbol(op) {
  switch (op) {
    case '+': return '+';
    case '-': return '−';
    case '*': return '×';
    case '/': return '÷';
    default: return op;
  }
}

export function triggerHaptic(type = 'digit') {
  if (!hapticsEnabled || typeof navigator === 'undefined' || !navigator.vibrate) {
    return;
  }
  switch (type) {
    case 'digit':
      navigator.vibrate(10);
      break;
    case 'operator':
    case 'function':
      navigator.vibrate(15);
      break;
    case 'equals':
      navigator.vibrate([20, 30, 20]);
      break;
    case 'clear':
      navigator.vibrate(25);
      break;
    default:
      navigator.vibrate(10);
  }
}

function updateUI() {
  const elCurrent = document.getElementById('display-current');
  const elExpression = document.getElementById('display-expression');
  if (elCurrent) {
    elCurrent.textContent = state.displayValue;
    adjustFontSize(elCurrent, state.displayValue);
  }
  if (elExpression) {
    elExpression.textContent = state.expression || ' ';
  }
  highlightActiveOperator();
}

function adjustFontSize(element, text) {
  if (text.length > 10) {
    element.style.fontSize = '2.2rem';
  } else if (text.length > 7) {
    element.style.fontSize = '3.0rem';
  } else {
    element.style.fontSize = '3.8rem';
  }
}

function highlightActiveOperator() {
  const buttons = document.querySelectorAll('.btn-operator');
  buttons.forEach(btn => {
    const opAction = btn.getAttribute('data-action');
    const opMap = { add: '+', subtract: '-', multiply: '*', divide: '/' };
    if (state.waitingForSecondOperand && state.operator === opMap[opAction]) {
      btn.classList.add('active-operator');
    } else {
      btn.classList.remove('active-operator');
    }
  });
}

function renderHistory() {
  const list = document.getElementById('history-list');
  if (!list) return;
  if (state.history.length === 0) {
    list.innerHTML = '<li class="history-empty">No calculations yet</li>';
    return;
  }
  list.innerHTML = state.history.map(item => `
    <li class="history-item" data-val="${item.result}">
      <div class="history-item-exp">${item.expression}</div>
      <div class="history-item-res">= ${item.result}</div>
    </li>
  `).join('');

  list.querySelectorAll('.history-item').forEach(item => {
    item.addEventListener('click', () => {
      const val = item.getAttribute('data-val');
      if (val) {
        state.displayValue = val;
        state.waitingForSecondOperand = false;
        updateUI();
        closeHistory();
      }
    });
  });
}

function openHistory() {
  document.getElementById('history-drawer')?.classList.remove('closed');
  document.getElementById('history-overlay')?.classList.remove('hidden');
}

function closeHistory() {
  document.getElementById('history-drawer')?.classList.add('closed');
  document.getElementById('history-overlay')?.classList.add('hidden');
}

function setupEventListeners() {
  const grid = document.querySelector('.keypad-grid');
  if (grid) {
    grid.addEventListener('click', (e) => {
      const target = e.target.closest('.calc-btn');
      if (!target) return;
      const action = target.getAttribute('data-action');
      const value = target.getAttribute('data-value');

      switch (action) {
        case 'digit':
          if (value) inputDigit(value);
          break;
        case 'decimal':
          inputDecimal();
          break;
        case 'add':
          setOperation('+');
          break;
        case 'subtract':
          setOperation('-');
          break;
        case 'multiply':
          setOperation('*');
          break;
        case 'divide':
          setOperation('/');
          break;
        case 'equals':
          calculate();
          break;
        case 'clear':
          clear();
          break;
        case 'sign':
          toggleSign();
          break;
        case 'percent':
          percent();
          break;
      }
    });
  }

  window.addEventListener('keydown', (e) => {
    if (e.key >= '0' && e.key <= '9') {
      inputDigit(e.key);
    } else if (e.key === '.') {
      inputDecimal();
    } else if (e.key === '+' || e.key === '-' || e.key === '*' || e.key === '/') {
      setOperation(e.key);
    } else if (e.key === 'Enter' || e.key === '=') {
      e.preventDefault();
      calculate();
    } else if (e.key === 'Escape' || e.key.toLowerCase() === 'c') {
      clear();
    } else if (e.key === '%') {
      percent();
    }
  });

  document.getElementById('btn-history')?.addEventListener('click', openHistory);
  document.getElementById('btn-close-history')?.addEventListener('click', closeHistory);
  document.getElementById('history-overlay')?.addEventListener('click', closeHistory);
  document.getElementById('btn-clear-history')?.addEventListener('click', () => {
    state.history = [];
    renderHistory();
  });

  const btnTheme = document.getElementById('btn-theme-toggle');
  btnTheme?.addEventListener('click', () => {
    const container = document.getElementById('app-container');
    if (container) {
      const isDark = container.classList.contains('dark-theme');
      container.classList.toggle('dark-theme', !isDark);
      container.classList.toggle('light-theme', isDark);
      document.querySelector('meta[name="theme-color"]')?.setAttribute('content', isDark ? '#ffffff' : '#121214');
    }
  });

  const btnHaptic = document.getElementById('btn-haptic-toggle');
  btnHaptic?.addEventListener('click', () => {
    hapticsEnabled = !hapticsEnabled;
    btnHaptic.classList.toggle('active', hapticsEnabled);
  });
}

// Register Service Worker for offline PWA functionality
if ('serviceWorker' in navigator && window.location.protocol.startsWith('http')) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').catch((err) => {
      console.warn('Service Worker registration skipped or failed:', err);
    });
  });
}

// Initialize on DOM ready
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      setupEventListeners();
      updateUI();
    });
  } else {
    setupEventListeners();
    updateUI();
  }
}

/* ==========================================================================
   Mobile Calculator Core Theme & Responsive Layout
   ========================================================================== */

:root {
  --font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --safe-area-top: env(safe-area-inset-top, 0px);
  --safe-area-bottom: env(safe-area-inset-bottom, 0px);
  --safe-area-left: env(safe-area-inset-left, 0px);
  --safe-area-right: env(safe-area-inset-right, 0px);
}

.dark-theme {
  --bg-color: #121214;
  --surface-color: #1e1e24;
  --text-primary: #f5f5f7;
  --text-secondary: #8e8e93;
  --btn-digit-bg: #2c2c2e;
  --btn-digit-text: #ffffff;
  --btn-digit-active: #3a3a3c;
  --btn-func-bg: #48484a;
  --btn-func-text: #ffffff;
  --btn-func-active: #636366;
  --btn-op-bg: #ff9f0a;
  --btn-op-text: #ffffff;
  --btn-op-active: #d68307;
  --btn-op-highlight: #ffffff;
  --btn-op-highlight-text: #ff9f0a;
  --drawer-bg: #1c1c1e;
  --border-color: #38383a;
}

.light-theme {
  --bg-color: #f2f2f7;
  --surface-color: #ffffff;
  --text-primary: #000000;
  --text-secondary: #6e6e73;
  --btn-digit-bg: #ffffff;
  --btn-digit-text: #000000;
  --btn-digit-active: #e5e5ea;
  --btn-func-bg: #d1d1d6;
  --btn-func-text: #000000;
  --btn-func-active: #c7c7cc;
  --btn-op-bg: #ff9f0a;
  --btn-op-text: #ffffff;
  --btn-op-active: #d68307;
  --btn-op-highlight: #000000;
  --btn-op-highlight-text: #ffffff;
  --drawer-bg: #ffffff;
  --border-color: #e5e5ea;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: var(--font-family);
  background-color: #000000;
}

.app-container {
  width: 100%;
  max-width: 480px;
  height: 100%;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  background-color: var(--bg-color);
  color: var(--text-primary);
  padding-top: var(--safe-area-top);
  padding-bottom: var(--safe-area-bottom);
  padding-left: var(--safe-area-left);
  padding-right: var(--safe-area-right);
  position: relative;
  overflow: hidden;
  transition: background-color 0.25s ease, color 0.25s ease;
}

.app-header {
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
}

.header-title {
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 1px;
  color: var(--text-secondary);
}

.header-left, .header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.icon-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  padding: 8px;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.15s, color 0.15s;
}

.icon-btn:active {
  background-color: rgba(255, 255, 255, 0.1);
}

.icon-btn.active {
  color: var(--btn-op-bg);
}

.calculator-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 16px;
}

.display-section {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-end;
  padding: 12px 16px;
  min-height: 120px;
}

.display-expression {
  font-size: 1.25rem;
  color: var(--text-secondary);
  min-height: 1.5rem;
  margin-bottom: 4px;
  word-break: break-all;
  text-align: right;
}

.display-current {
  font-size: 3.8rem;
  font-weight: 300;
  line-height: 1.1;
  word-break: break-all;
  text-align: right;
  max-width: 100%;
  transition: font-size 0.1s ease;
}

.keypad-section {
  width: 100%;
  margin-top: 16px;
}

.keypad-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.calc-btn {
  border: none;
  outline: none;
  height: 72px;
  border-radius: 36px;
  font-size: 1.85rem;
  font-weight: 400;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.08s ease, filter 0.08s ease, background-color 0.15s ease;
}

.calc-btn:active {
  transform: scale(0.94);
}

.btn-digit {
  background-color: var(--btn-digit-bg);
  color: var(--btn-digit-text);
}
.btn-digit:active {
  background-color: var(--btn-digit-active);
}

.btn-function {
  background-color: var(--btn-func-bg);
  color: var(--btn-func-text);
  font-size: 1.6rem;
  font-weight: 500;
}
.btn-function:active {
  background-color: var(--btn-func-active);
}

.btn-operator, .btn-equals {
  background-color: var(--btn-op-bg);
  color: var(--btn-op-text);
  font-size: 2rem;
  font-weight: 500;
}
.btn-operator:active, .btn-equals:active {
  background-color: var(--btn-op-active);
}

.btn-operator.active-operator {
  background-color: var(--btn-op-highlight);
  color: var(--btn-op-highlight-text);
}

.btn-zero {
  grid-column: span 2;
  border-radius: 36px;
  justify-content: flex-start;
  padding-left: 28px;
}

/* History Drawer */
.history-drawer {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  max-height: 70%;
  height: 480px;
  background-color: var(--drawer-bg);
  border-top-left-radius: 20px;
  border-top-right-radius: 20px;
  z-index: 100;
  display: flex;
  flex-direction: column;
  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.4);
  transform: translateY(0);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.history-drawer.closed {
  transform: translateY(105%);
}

.history-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-color);
}

.history-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.text-btn {
  background: none;
  border: none;
  color: var(--btn-op-bg);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
}

.history-list {
  list-style: none;
  overflow-y: auto;
  padding: 12px 20px;
  flex: 1;
}

.history-empty {
  color: var(--text-secondary);
  text-align: center;
  margin-top: 40px;
}

.history-item {
  padding: 12px 0;
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
}

.history-item-exp {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.history-item-res {
  color: var(--text-primary);
  font-size: 1.4rem;
  font-weight: 600;
  margin-top: 2px;
}

.history-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 90;
  opacity: 1;
  transition: opacity 0.3s ease;
}

.history-overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

@media (max-height: 600px) {
  .calc-btn {
    height: 52px;
    border-radius: 26px;
    font-size: 1.4rem;
  }
  .btn-zero {
    padding-left: 20px;
  }
  .display-section {
    min-height: 80px;
    padding: 8px 12px;
  }
  .display-current {
    font-size: 2.8rem;
  }
}

/**
 * Service Worker for Offline Calculator Execution
 */

const CACHE_NAME = 'calc-pwa-v1.0.0';
const ASSETS_TO_CACHE = [
  './',
  './index.html',
  './manifest.json',
  './assets/calculator.js',
  './assets/theme.css'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS_TO_CACHE);
    }).then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keyList) => {
      return Promise.all(
        keyList.map((key) => {
          if (key !== CACHE_NAME) {
            return caches.delete(key);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      if (cachedResponse) {
        return cachedResponse;
      }
      return fetch(event.request).then((networkResponse) => {
        if (!networkResponse || networkResponse.status !== 200 || networkResponse.type !== 'basic') {
          return networkResponse;
        }
        const responseToCache = networkResponse.clone();
        caches.open(CACHE_NAME).then((cache) => {
          cache.put(event.request, responseToCache);
        });
        return networkResponse;
      }).catch(() => {
        if (event.request.headers.get('accept')?.includes('text/html')) {
          return caches.match('./index.html');
        }
      });
    })
  );
});
